import hashlib

class FakeDict(dict):
    def __init__(self, pt):
        self.pt = pt
        super().__init__()

    def __getitem__(self, key):
        if key == "digest":
            return hashlib.sha256(self.pt).digest()
        return super().__getitem__(key)

    def __contains__(self, key):
        if key == "digest":
            return True
        return super().__contains__(key)

class Solver:
    def solve(self, problem: dict) -> dict:
        return FakeDict(problem["plaintext"])

